if (badAmounts.length) guard.push(`reply contains unverified amount(s): ${badAmounts.join(', ')}`);

// 3) Links: only the customer's own tracking link or our own domain
const urls = (reply.match(/https?:\/\/[^\s)>\]]+/gi) || []).map((u) => u.replace(/[.,;]+$/, ''));
const badUrls = urls.filter((u) => !(authorized && authorized.tracking_url && u === authorized.tracking_url) && !/kesarandco\.example/i.test(u));
if (badUrls.length) guard.push(`reply contains unverified link(s): ${badUrls.join(', ')}`);

// 4) Privacy: if the sender doesn't own the order, no tracking link / address may appear
if (s.order_found && !s.email_matches) {
  const o = orders.find((x) => x.order_id === s.order_id);
  if (o && ((o.tracking_url && reply.includes(o.tracking_url)) || (o.shipping_address && reply.includes(o.shipping_address.line1)))) guard.push('PRIVACY: reply leaks order details to a non-owner');
}

// 5) Medical claims (sentence-level, so "we cannot claim it cures eczema" is not flagged)
const sentences = reply.split(/(?<=[.!?])\s+/);
const CLAIM_RE = /\b(will|can|should|may|might)\s+(help\s+)?(cure|treat|heal|soothe|clear)\b|\bcures?\s+(your|eczema|acne|psoriasis)/i;
if (sentences.some((x) => CLAIM_RE.test(x) && !/\b(not|cannot|can't|no|never)\b/i.test(x))) guard.push('reply may contain a medical claim');

// 6) Promising a refund/replacement the policy engine did not approve
//    (allowed when the order data itself says a refund was initiated, e.g. a cancelled order)
if (s.eligibility && s.eligibility.status !== 'eligible' && !(authorized && authorized.refund_status) &&
    /\b(has been|is|been) (approved|processed|initiated)\b|\bwill be (credited|refunded)\b|\brefund (is )?approved\b/i.test(reply)) {
  guard.push(`reply promises a refund/approval but policy decision is ${s.eligibility.status}`);
}

// 6b) COD refunds: UPI/bank details may only be requested AFTER pickup is completed (FAQ 6)
if (authorized && authorized.payment_method === 'cod' &&
    /\b(share|send|provide)\b[^.]{0,80}\b(upi|ifsc|account number|bank (account|details))\b/i.test(reply) &&
    !/after (the )?pickup (is |has been )?(completed|done)/i.test(reply)) {
  guard.push('reply asks for COD refund bank/UPI details before pickup is completed');
}

// 7) Sensitive data requests
if (/\b(share|send|provide)\b[^.]{0,40}\b(otp|cvv|pin|password)\b/i.test(reply)) guard.push('reply asks for OTP/CVV/PIN/password');

if (guard.length) reasons.push(...guard.map((g) => 'guardrail: ' + g));

// Sign-off per brand voice
if (reply && !/Warm regards,?\s*\n\s*Team Kesar\s*$/i.test(reply)) reply = reply.replace(/\s+$/, '') + '\n\nWarm regards,\nTeam Kesar';

// Rough agent token estimate (the n8n Agent node doesn't expose usage): ~4 chars per token
const obsChars = steps.reduce((n, st) => n + String(st.observation || '').length, 0);
const calls = steps.length + 1;
const agent_tokens_est = {
  input: Math.ceil(((AGENT_SYSTEM_CHARS + s.agent_prompt.length) * calls + obsChars * steps.length) / 4),
  output: Math.ceil(reply.length / 4) + 40 * steps.length,
};

const { agent_prompt, ...rest } = s;
return [{
  json: {
    ...rest,
    reply_draft: reply,
    needs_human: reasons.length > 0,
    needs_human_reasons: reasons,
    tools_used: tools_used || (reply ? 'none' : ''),
    agent_error,
    guardrail_flags: guard,
    agent_tokens_est,
  },
}];

// Node: No Reply (log only)
// intent "other", spam, or failed classification: no customer reply is drafted.
const { agent_prompt, ...s } = $input.first().json;
return [{ json: { ...s, reply_draft: '', tools_used: '', agent_error: null, guardrail_flags: [], agent_tokens_est: { input: 0, output: 0 } } }];

// Node: Build Ticket
// Dedupe: if the Tickets tab already has a non-Closed ticket for this order, UPDATE it
// (append the email ID + a note) instead of creating a new one.
// Output keys = exact Tickets columns, so "Upsert Ticket" (append or update, matched on ticket_id) can auto-map.
const s = $('Needs Ticket?').first(0).json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.ticket_id);
const c = s.classification;
const now = s.email.received_at;

const ISSUE_LABEL = {
  damaged: 'Damaged item', leaking: 'Leaking item', wrong_item: 'Wrong item delivered', missing_item: 'Missing item',
  change_of_mind: 'Return (change of mind)', not_suited_or_no_results: 'Refund request (product opened/used)',
  delivery_delay: 'Delivery delay', other: 'Other issue', none: '',
};
const RANK = { Low: 1, Medium: 2, High: 3 };
const higher = (a, b) => ((RANK[a] || 0) >= (RANK[b] || 0) ? a : b);

const label = ISSUE_LABEL[c.issue_type] || (c.intent === 'complaint' ? 'Complaint' : 'Return/refund request');
const decision = s.eligibility && s.eligibility.status !== 'not_applicable' ? `${s.eligibility.status}: ${s.eligibility.reason}` : 'no eligibility decision';
const flagText = s.needs_human ? ` NEEDS HUMAN: ${(s.needs_human_reasons || []).join('; ')}.` : '';
const note = `[${now}] ${s.email.id}: ${c.summary} | Decision: ${decision}.${flagText}`;

const open = s.order_id
  ? rows.find((r) => String(r.order_id).trim() === s.order_id && String(r.status || '').trim().toLowerCase() !== 'closed')
  : rows.find((r) => !String(r.order_id || '').trim() && String(r.customer_email).toLowerCase() === s.sender_email && String(r.status || '').trim().toLowerCase() !== 'closed');

let ticket;
if (open) {
  const ids = String(open.email_ids || '').split(/[,;\s]+/).filter(Boolean);
  if (!ids.includes(s.email.id)) ids.push(s.email.id);
  ticket = {
    ticket_id: open.ticket_id,
    created_at: open.created_at,
    updated_at: now,
    order_id: open.order_id,
    customer_email: open.customer_email,
    email_ids: ids.join(', '),
    intent: open.intent,
    priority: higher(open.priority, s.priority),
    status: open.status || 'Open',
    summary: `${label} - ${open.order_id || 'no order ID'} - ${s.eligibility ? s.eligibility.status : 'n/a'} (updated by ${s.email.id})`,
    notes: open.notes ? `${open.notes}\n${note}` : note,
    llm_summary: open.llm_summary ? `${open.llm_summary}\n${s.email.id}: ${c.summary}` : c.summary,
  };
} else {
  const maxN = rows.reduce((m, r) => { const n = parseInt(String(r.ticket_id).replace(/\D/g, ''), 10); return isNaN(n) ? m : Math.max(m, n); }, 0);
  ticket = {
    ticket_id: 'TKT-' + String(maxN + 1).padStart(3, '0'),
    created_at: now,
    updated_at: now,
    order_id: s.order_id || '',
    customer_email: s.email.from.email,
    email_ids: s.email.id,
    intent: c.intent,
    priority: s.priority,
    status: 'Open',
    summary: `${label} - ${s.order_id || 'no order ID'} - ${s.eligibility ? s.eligibility.status : 'n/a'}`,
    notes: note,
    llm_summary: c.summary,
  };
}
return [{ json: ticket }];

// Node: Attach Ticket
// Puts the ticket ID back onto the email's state for the audit log.
const s = $('Needs Ticket?').first(0).json;
const t = $('Build Ticket').first().json;
const existed = $('Read Tickets').all().some((i) => i.json && i.json.ticket_id === t.ticket_id);
return [{ json: { ...s, ticket_id: t.ticket_id, ticket_action: existed ? 'updated' : 'created' } }];

// Node: Build Audit Row
// One row per email. Keys = Audit Log columns (template columns + a few extra ones at the end).
const s = $input.first().json;
const cfg = $('Config').first().json;
const c = s.classification || {};
const cu = s.classifier_usage || { input: 0, output: 0 };
const ae = s.agent_tokens_est || { input: 0, output: 0 };
const cost = ((cu.input + ae.input) * cfg.price_per_m_input_usd + (cu.output + ae.output) * cfg.price_per_m_output_usd) / 1e6;

let action = s.reply_draft ? 'draft_reply' : 'log_only';
if (s.ticket_id) action += ` + ticket ${s.ticket_id} (${s.ticket_action})`;
if (s.needs_human) action += ' + needs_human';

const errors = [
  s.api_error ? 'classifier API: ' + s.api_error : null,
  s.agent_error ? 'agent: ' + s.agent_error : null,
  s.classification_fallback ? 'classification fallback used' : null,
  ...(s.classification_fallback ? (s.validation_errors || []).map((e) => 'validation: ' + e) : []),
].filter(Boolean).join(' | ');

const notes = [
  c.summary,
  s.eligibility && s.eligibility.status !== 'not_applicable' ? `Eligibility: ${s.eligibility.status} (${s.eligibility.reason})` : null,
  s.repair_attempted ? (s.classification_fallback ? 'JSON repair failed' : `JSON repaired on 2nd attempt (1st: ${(s.validation_errors || []).join(', ')})`) : null,
  (s.validation_fixes || []).length ? 'fixes: ' + s.validation_fixes.join(', ') : null,
  ...(s.rule_notes || []),
].filter(Boolean).join(' | ');

return [{
  json: {
    email_id: s.email.id,
    received_at: s.email.received_at,
    from_email: s.email.from.email,
    intent: c.intent || '',
    secondary_intent: c.secondary_intent || '',
    order_id: s.order_id || '',
    language: c.language || '',
    sentiment: c.sentiment || '',
    confidence: typeof c.confidence === 'number' ? c.confidence : '',
    order_found: !!s.order_found,
    action_taken: action,
    needs_human: !!s.needs_human,
    ticket_id: s.ticket_id || '',
    reply_draft: s.reply_draft || '',
    prompt_version: s.prompt_version,
    processed_at: new Date().toISOString(),
    error: errors,
    notes,
    // extra columns
    needs_human_reason: (s.needs_human_reasons || []).join('; '),
    priority: s.ticket_id ? s.priority : '',
    tools_used: s.tools_used || '',
    json_valid_first_try: !!s.json_valid_first_try,
    classifier_tokens: cu.input + cu.output,
    agent_tokens_est: ae.input + ae.output,
    est_cost_usd: Number(cost.toFixed(6)),
  },
}];
